package toolchain

import (
	"github.com/funtimecoding/soil/pkg/assert"
	"testing"
)

func TestImporterRekeyedWhenTypeCommentChanges(t *testing.T) {
	assert.Integer(
		t,
		4,
		extractionsAfterEdit(
			t,
			"package alfa\n\n//bravo:charlie because delta\ntype Alfa struct{}\n\ntype echo struct{}\n",
		),
	)
}

func TestImporterRekeyedWhenTypeFileTurnsGenerated(t *testing.T) {
	assert.Integer(
		t,
		4,
		extractionsAfterEdit(
			t,
			"// Code generated by foxtrot. DO NOT EDIT.\n\npackage alfa\n\ntype Alfa struct{}\n\ntype echo struct{}\n",
		),
	)
}

func TestImporterRekeyedWhenPackageNameChanges(t *testing.T) {
	assert.Integer(
		t,
		4,
		extractionsAfterEdit(
			t,
			"package foxtrot\n\ntype Alfa struct{}\n\ntype echo struct{}\n",
		),
	)
}

func TestImporterKeptWhenUnexportedTypeCommentChanges(t *testing.T) {
	assert.Integer(
		t,
		3,
		extractionsAfterEdit(
			t,
			"package alfa\n\ntype Alfa struct{}\n\n//bravo:charlie because delta\ntype echo struct{}\n",
		),
	)
}
